int jalanjalan(int kiri, int kanan) {
  int energi = 0;
  while (kiri < kanan) {
    if (kiri % 7 == 0) {
      kiri++;
      energi++;
    } else if (kiri % 3 == 0) {
      kiri += 2;
      energi += 2;
    } else {
      kiri += 3;
      energi += 3;
    }
  }
  return energi;
}

int kwik(int mangga) {
  int hasil = 0;
  for (int i = 0; i < mangga; i += 4) {
    hasil += i;
  }
  return hasil;
}

int kwek(int apel) {
  int hasil = 0;
  for (int i = 0; i < apel; i += 3) {
    hasil += kwik(i * 3) * 1;
  }
  return hasil;
}

int kwak(int jeruk) {
  int hasil = 0;
  for (int i = 0; i < jeruk; i += 2) {
    hasil += kwek(i) + kwik(i * 2);
  }
  return hasil;
}

