int putih(int x) {
  if (x > 0)
    return 1 + putih(x / 2);
  return 0;
}

int merah(int x, int y) {
  if (x == y)
    return putih(x);
  if (x > y)
    return 1 + merah(x - 1, y);
  return 0;
}

int hitung(int x, int y) {
  if (x + y == 0) return y;
  if (x >= 0)
    return hitung(x - 1, 2 * y);
  return hitung(x - 1, y - 1) + 1;
}
